Here's a complete, self-contained Account Settings screen for a React Native app (iOS + Android), written in TypeScript using only core `react-native` APIs — no extra dependencies required.

```tsx
// AccountSettingsScreen.tsx
import React, { useCallback, useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  Image,
  Platform,
  Pressable,
  SafeAreaView,
  ScrollView,
  StyleSheet,
  Switch,
  Text,
  View,
} from 'react-native';

// ---------- Types ----------

export interface AccountProfile {
  name: string;
  email: string;
  avatarUrl?: string;
}

interface AccountSettingsScreenProps {
  profile: AccountProfile;
  onEditProfile: () => void;
  onChangePassword: () => void;
  onOpenNotificationSettings: () => void;
  onOpenPrivacyPolicy: () => void;
  onOpenHelp: () => void;
  onSignOut: () => void;
  /** Must perform the actual deletion (API call) and resolve/reject accordingly. */
  onDeleteAccount: () => Promise<void>;
}

type RowVariant = 'navigation' | 'toggle' | 'destructive';

interface RowProps {
  label: string;
  subtitle?: string;
  variant?: RowVariant;
  value?: boolean;
  onValueChange?: (value: boolean) => void;
  onPress?: () => void;
  disabled?: boolean;
  loading?: boolean;
  isLast?: boolean;
}

// ---------- Reusable row ----------

function SettingsRow({
  label,
  subtitle,
  variant = 'navigation',
  value,
  onValueChange,
  onPress,
  disabled,
  loading,
  isLast,
}: RowProps) {
  const isDestructive = variant === 'destructive';
  const isToggle = variant === 'toggle';

  const content = (
    <View style={[styles.row, !isLast && styles.rowDivider]}>
      <View style={styles.rowTextContainer}>
        <Text
          style={[styles.rowLabel, isDestructive && styles.rowLabelDestructive]}
        >
          {label}
        </Text>
        {subtitle ? <Text style={styles.rowSubtitle}>{subtitle}</Text> : null}
      </View>

      {loading ? (
        <ActivityIndicator size="small" />
      ) : isToggle ? (
        <Switch
          value={value}
          onValueChange={onValueChange}
          disabled={disabled}
          accessibilityRole="switch"
          accessibilityLabel={label}
          accessibilityState={{ checked: !!value }}
        />
      ) : (
        !isDestructive && <Text style={styles.chevron}>›</Text>
      )}
    </View>
  );

  if (isToggle) {
    // Toggle rows don't need a press handler on the row itself.
    return content;
  }

  return (
    <Pressable
      onPress={onPress}
      disabled={disabled || loading}
      accessibilityRole="button"
      accessibilityLabel={label}
      hitSlop={8}
      style={({ pressed }) => [
        pressed && !disabled && styles.rowPressed,
      ]}
    >
      {content}
    </Pressable>
  );
}

function SettingsSection({
  title,
  children,
}: {
  title?: string;
  children: React.ReactNode;
}) {
  return (
    <View style={styles.section}>
      {title ? <Text style={styles.sectionTitle}>{title}</Text> : null}
      <View style={styles.sectionCard}>{children}</View>
    </View>
  );
}

// ---------- Main screen ----------

export default function AccountSettingsScreen({
  profile,
  onEditProfile,
  onChangePassword,
  onOpenNotificationSettings,
  onOpenPrivacyPolicy,
  onOpenHelp,
  onSignOut,
  onDeleteAccount,
}: AccountSettingsScreenProps) {
  const [pushEnabled, setPushEnabled] = useState(true);
  const [faceIdEnabled, setFaceIdEnabled] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const confirmSignOut = useCallback(() => {
    Alert.alert('Sign out?', 'You can sign back in at any time.', [
      { text: 'Cancel', style: 'cancel' },
      { text: 'Sign Out', style: 'destructive', onPress: onSignOut },
    ]);
  }, [onSignOut]);

  const performDelete = useCallback(async () => {
    setIsDeleting(true);
    try {
      await onDeleteAccount();
    } catch (error) {
      Alert.alert(
        'Couldn\u2019t delete account',
        error instanceof Error
          ? error.message
          : 'Something went wrong. Please try again.',
        [{ text: 'OK' }],
      );
    } finally {
      setIsDeleting(false);
    }
  }, [onDeleteAccount]);

  const confirmDeleteAccount = useCallback(() => {
    Alert.alert(
      'Delete account',
      'This permanently deletes your account and all of your data. This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: performDelete,
        },
      ],
      { cancelable: true },
    );
  }, [performDelete]);

  return (
    <SafeAreaView style={styles.safeArea}>
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        keyboardShouldPersistTaps="handled"
      >
        <Text style={styles.screenTitle}>Account</Text>

        {/* Profile row */}
        <Pressable
          onPress={onEditProfile}
          accessibilityRole="button"
          accessibilityLabel={`Edit profile, ${profile.name}`}
          style={({ pressed }) => [
            styles.profileRow,
            pressed && styles.rowPressed,
          ]}
        >
          {profile.avatarUrl ? (
            <Image
              source={{ uri: profile.avatarUrl }}
              style={styles.avatar}
              accessibilityIgnoresInvertColors
            />
          ) : (
            <View style={[styles.avatar, styles.avatarFallback]}>
              <Text style={styles.avatarInitial}>
                {profile.name.charAt(0).toUpperCase()}
              </Text>
            </View>
          )}

          <View style={styles.profileTextContainer}>
            <Text style={styles.profileName} numberOfLines={1}>
              {profile.name}
            </Text>
            <Text style={styles.profileEmail} numberOfLines={1}>
              {profile.email}
            </Text>
          </View>

          <Text style={styles.chevron}>›</Text>
        </Pressable>

        <SettingsSection title="Preferences">
          <SettingsRow
            label="Push Notifications"
            variant="toggle"
            value={pushEnabled}
            onValueChange={setPushEnabled}
          />
          <SettingsRow
            label="Face ID / Fingerprint Unlock"
            variant="toggle"
            value={faceIdEnabled}
            onValueChange={setFaceIdEnabled}
            isLast
          />
        </SettingsSection>

        <SettingsSection title="Security">
          <SettingsRow label="Change Password" onPress={onChangePassword} />
          <SettingsRow
            label="Notification Settings"
            onPress={onOpenNotificationSettings}
            isLast
          />
        </SettingsSection>

        <SettingsSection title="Support">
          <SettingsRow label="Help & Support" onPress={onOpenHelp} />
          <SettingsRow
            label="Privacy Policy"
            onPress={onOpenPrivacyPolicy}
            isLast
          />
        </SettingsSection>

        <SettingsSection>
          <SettingsRow label="Sign Out" onPress={confirmSignOut} isLast />
        </SettingsSection>

        <SettingsSection>
          <SettingsRow
            label="Delete Account"
            subtitle="Permanently delete your account and data"
            variant="destructive"
            onPress={confirmDeleteAccount}
            loading={isDeleting}
            disabled={isDeleting}
            isLast
          />
        </SettingsSection>
      </ScrollView>
    </SafeAreaView>
  );
}

// ---------- Styles ----------

const CARD_BACKGROUND = '#FFFFFF';
const SCREEN_BACKGROUND = '#F2F2F7';
const BORDER_COLOR = '#E5E5EA';
const TEXT_PRIMARY = '#1C1C1E';
const TEXT_SECONDARY = '#8A8A8E';
const DESTRUCTIVE = '#FF3B30';
const ACCENT = '#007AFF';

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: SCREEN_BACKGROUND,
  },
  scrollContent: {
    paddingBottom: 32,
  },
  screenTitle: {
    fontSize: 28,
    fontWeight: '700',
    color: TEXT_PRIMARY,
    paddingHorizontal: 16,
    paddingTop: Platform.select({ ios: 8, android: 16, default: 16 }),
    paddingBottom: 12,
  },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: CARD_BACKGROUND,
    marginHorizontal: 16,
    marginBottom: 20,
    padding: 16,
    borderRadius: 12,
    ...Platform.select({
      ios: {
        shadowColor: '#000',
        shadowOpacity: 0.05,
        shadowOffset: { width: 0, height: 1 },
        shadowRadius: 2,
      },
      android: {
        elevation: 1,
      },
    }),
  },
  avatar: {
    width: 56,
    height: 56,
    borderRadius: 28,
    backgroundColor: BORDER_COLOR,
  },
  avatarFallback: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  avatarInitial: {
    fontSize: 22,
    fontWeight: '600',
    color: ACCENT,
  },
  profileTextContainer: {
    flex: 1,
    marginLeft: 14,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
    color: TEXT_PRIMARY,
  },
  profileEmail: {
    fontSize: 14,
    color: TEXT_SECONDARY,
    marginTop: 2,
  },
  section: {
    marginBottom: 20,
  },
  sectionTitle: {
    fontSize: 13,
    fontWeight: '600',
    color: TEXT_SECONDARY,
    textTransform: 'uppercase',
    marginLeft: 28,
    marginBottom: 6,
  },
  sectionCard: {
    backgroundColor: CARD_BACKGROUND,
    marginHorizontal: 16,
    borderRadius: 12,
    overflow: 'hidden',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    minHeight: 50,
    paddingHorizontal: 16,
    paddingVertical: 12,
  },
  rowDivider: {
    borderBottomWidth: 1,
    borderBottomColor: BORDER_COLOR,
  },
  rowPressed: {
    backgroundColor: Platform.select({
      ios: '#EAEAEA',
      android: '#E0E0E0',
      default: '#EAEAEA',
    }),
  },
  rowTextContainer: {
    flex: 1,
    marginRight: 12,
  },
  rowLabel: {
    fontSize: 16,
    color: TEXT_PRIMARY,
  },
  rowLabelDestructive: {
    color: DESTRUCTIVE,
    fontWeight: '500',
  },
  rowSubtitle: {
    fontSize: 13,
    color: TEXT_SECONDARY,
    marginTop: 2,
  },
  chevron: {
    fontSize: 20,
    color: TEXT_SECONDARY,
  },
});
```

Notes on cross-platform behavior and the design choices baked in:

- **No navigation library assumed.** Callbacks (`onEditProfile`, `onSignOut`, `onDeleteAccount`, etc.) are passed in as props so this screen drops into whatever navigation setup (React Navigation, Expo Router, etc.) the app already uses.
- **Delete confirmation** uses the native `Alert.alert` with a `destructive`-styled button. On iOS this renders red; on Android `Alert` ignores the style and shows standard buttons, which is expected native behavior rather than a bug. `onDeleteAccount` is awaited with a loading spinner (`isDeleting`) and disabled state to prevent double-taps, and failures surface a second alert instead of silently failing.
- **Platform-specific styling**: shadow on iOS vs `elevation` on Android for the profile card, and slightly different top padding to match each platform's status bar conventions.
- **Accessibility**: rows use `accessibilityRole="button"`/`"switch"`, labels, and `accessibilityState` for switches so VoiceOver/TalkBack announce state correctly; `hitSlop` enlarges tap targets.
- **`Pressable`** is used instead of `TouchableOpacity` for consistent, platform-correct press feedback on both iOS and Android.

If you want, I can wire this up for a specific navigation setup (e.g., React Navigation's `useNavigation`) or add a stricter "type DELETE to confirm" second step before calling `onDeleteAccount` — just say which.
